      position: relative;
    }

    .message-bubble:before,
    .message-bubble:after {
      content: "";
      position: absolute;
      bottom: -10px;
    }

    .message-bubble:before {
      border-style: solid;
      border-width: 10px 10px 0 0;
      border-color: #fff transparent transparent transparent;
      left: 100%;
      margin-left: 10px;
    }

    .message-bubble:after {
      border-style: solid;
      border-width: 10px 10px 0 0;
      border-color: #f9f9f9 transparent transparent transparent;
      left: 100%;
      margin-left: 10px;
    }

    .message-bubble-bot {
      background-color: #2196F3;
      color: #fff;
    }

    .message-bubble-bot:before {
      border-color: #2196F3 transparent transparent transparent;
    }

    .message-bubble-bot:after {
      border-color: #f9f9f9 transparent transparent transparent;
    }

    .message-text {
      font-size: 14px;
      line-height: 1.5;
      margin-left: 30px;
    }

    .message-text-bot {
      text-align: right;
    }

    .modal {
      display: none;
      position: fixed;
      z-index: 1;
      left: 0;
      top: 0;
      width: 100%;
      height: 100%;
      overflow: auto;
      background-color: rgb(0, 0, 0);
      background-color: rgba(0, 0, 0, 0.9);
    }

    .modal-content {
      background-color: #fefefe;
      margin: auto;
      padding: 20px;
      border: 1px solid #888;
      width: 80%;
      max-width: 600px;
    }

    .close {
      position: absolute;
      top: 15px;
      right: 25px;
      color: #000;
      font-size: 35px;
      font-weight: bold;
      transition: 0.3s;
    }

    .close:hover,
    .close:focus {
      color: #999;
    }

    .chat-history {
      max-height: 400px;
      overflow-y: auto;
    }
  </style>
</head>
<body>
  <div class="chat-container">
    <div id="chat" class="chat">
      <div class="message">
        <div class="message-bubble message-bubble-bot">
          <div class="message-text message-text-bot">Bot: Hello, how can I assist you?</div>
        </div>
      </div>
      <div class="message">
        <div class="message-bubble">
          <div class="message-text">User: I need help with my account.</div>
        </div>
      </div>
      <div class="message">
        <div class="message-bubble message-bubble-bot">
          <div class="message-text message-text-bot">Bot: Sure, I can help you with that. What seems to be the issue?</div>
        </div>
      </div>
      <div class="message">
        <div class="message-bubble">
          <div class="message-text">User: I forgot my password.</div>
        </div>
      </div>
    </div>
    <button id="show-modal">Show Chat History</button>

    <div id="modal" class="modal">
      <div class="modal-content">
        <span class="close">&times;</span>
        <div class="chat-history"></div>
      </div>
    </div>
  </div>

  <script>
    const chat = document.getElementById('chat');
    const showBtn = document.getElementById('show-modal');
    const modal = document.getElementById('modal');
    const closeBtn = modal.querySelector('.close');
    const chatHistory = modal.querySelector('.chat-history');

    // Add messages to chat history
    chat.querySelectorAll('.message').forEach(msg => {
      const clone = msg.cloneNode(true);
      chatHistory.appendChild(clone);
    });

    // Show modal with chat history
    showBtn.addEventListener('click', () => {
      modal.style.display = 'block';
      chatHistory.innerHTML = '';
      chat.querySelectorAll('.message').forEach(msg => {
        const clone = msg.cloneNode(true);
        chatHistory.appendChild(clone);
      });
    });

    // Close modal
    closeBtn.addEventListener('click', () => {
      modal.style.display = 'none';
    });

    // When the user clicks anywhere outside of the modal, close it
    window.addEventListener('click', (event) => {
      if (event.target === modal) {
        modal.style.display = 'none';
      }
    });
  </script>
</body>
